package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="order_number",nullable=false,unique=true,length=50) private String orderNumber; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id",nullable=false) private Customer customer; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @Column(nullable=false,length=30) private String status; @Column(name="ordered_at",nullable=false) private OffsetDateTime orderedAt; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public Warehouse getWarehouse(){return warehouse;} public void setWarehouse(Warehouse v){warehouse=v;} }
